mapper.sql:
f.MANAGERS_ID = #{managerId}

  AND cr.STATUS = #{status}


  AND cr.CREATED_AT >= #{fromDt}



  AND cr.CREATED_AT < #{toEx}



  AND (
       UPPER(f.NAME)      LIKE UPPER('%' || #{q} || '%')
    OR UPPER(cr.CATEGORY) LIKE UPPER('%' || #{q} || '%')
    OR UPPER(cr.EMAIL)    LIKE UPPER('%' || #{q} || '%')
    OR (cr.DESCRIPTION IS NOT NULL AND DBMS_LOB.INSTR(LOWER(cr.DESCRIPTION), LOWER(#{q})) > 0)
  )

mapper.delete:
DELETE FROM CITIZEN_REPORTS cr
WHERE cr.CITIZEN_REPORT_ID = #{id}
  AND EXISTS (
    SELECT 1 FROM FACILITIES f
     WHERE f.FACILITY_ID = cr.FACILITY_ID
       AND f.MANAGERS_ID = #{managerId}
  )
